import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);  // Armazena todos os clientes
  const [searchTerm, setSearchTerm] = useState('');  // Termo de busca
  const [isLoading, setIsLoading] = useState(false);  // Controla o carregamento
  const [showList, setShowList] = useState(false);  // Controla a visibilidade da lista

  // Função para carregar todos os clientes (chamada na montagem do componente)
  const fetchClientes = async () => {
    setIsLoading(true);  // Começa o carregamento
    try {
      const response = await axios.get('http://localhost:8080/clientes');
      setClientes(response.data);  // Atualiza o estado com a lista de clientes
      setShowList(true);  // Exibe a lista após o carregamento
    } catch (error) {
      console.error('Erro ao carregar clientes:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Filtra os clientes de acordo com o nome
  const handleSearch = () => {
    if (searchTerm) {
      return clientes.filter(cliente =>
        cliente.nome.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    return clientes;  // Retorna todos os clientes se não houver busca
  };

  return (
    <div className="cliente-list">
      {/* Campo de busca no canto superior direito */}
      <div className="search-box">
        <input
          type="text"
          placeholder="Buscar por nome..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}  // Atualiza o termo de busca
        />
        <button onClick={fetchClientes}>Buscar</button>
      </div>

      {/* Exibe os clientes após a busca */}
      {isLoading ? (
        <p>Carregando...</p>
      ) : (
        showList && (
          <ul className="clientes-ul">
            {handleSearch().length === 0 ? (
              <li>Nenhum cliente encontrado.</li>
            ) : (
              handleSearch().map(cliente => (
                <li key={cliente.id}>
                  {cliente.nome} - {cliente.email} - {cliente.telefone}
                </li>
              ))
            )}
          </ul>
        )
      )}
    </div>
  );
};

export default ClienteList;
